package domain

// Identifier types keep one entity's UUID from being passed where another is
// expected. Values are UUID v4 strings generated by the application.
type (
	RealmID       string
	UserID        string
	SessionID     string
	ClientID      string
	RoleID        string
	GroupID       string
	AuditEventID  string
	OutboxEventID string
	SigningKeyID  string
)
